// JobSearchOS returns already-scored postings; keep only strong matches
// and shape one item per posting for the rest of the workflow.
const MIN_SCORE = 80;
const jobs = ($input.first().json.jobs) || [];
return jobs
  .filter(j => (j.score ?? 0) >= MIN_SCORE)
  .map(j => ({ json: {
    id: j.id,
    title: j.title,
    company: j.company,
    score: j.score,
    jd: j.jd || j.description || '',
    recruiterEmail: j.recruiterEmail || '',
    breakdown: j.breakdown || {}
  }}));

