// Pull the draft text out of the LLM response and carry the job fields forward.
const ai = $input.first().json;
const draft = ai?.content?.[0]?.text || 'DRAFT UNAVAILABLE';
const job = $('Keep matches ≥ 80').item.json;
return [{ json: { ...job, draft } }];
